PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ( (?riskScore + ?allocationConcentration + ?goalVolatility - ?liquidityScore + ?scenarioChange) AS ?five_table_risk_pressure_score )
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScoreRaw)) AS ?riskScore)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScoreRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (MAX(xsd:decimal(?allocationPctRaw)) AS ?allocationConcentration)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasSectorAllocation ?sectorAllocation .
      ?sectorAllocation wm:allocationPct ?allocationPctRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?avgVolatilityPctRaw)) AS ?goalVolatility)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal wm:avgVolatilityPct ?avgVolatilityPctRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?liquidityScoreRaw)) AS ?liquidityScore)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:liquidityScore ?liquidityScoreRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPctRaw)) AS ?scenarioChange)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPctRaw .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:hasCashFlow ?cashFlow .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .
}
ORDER BY DESC(?five_table_risk_pressure_score) ?investorId
LIMIT 10

