SELECT ?segment
       (AVG(?scenarioChangePerInvestor) AS ?scenario_change)
       (AVG(?goalProgressPerInvestor) AS ?goal_progress)
       (AVG(?volatilityPerInvestor) AS ?volatility)
WHERE {
