      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?avgVolatilityPct)) AS ?volatilityPerInvestor)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:avgVolatilityPct ?avgVolatilityPct .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:segment ?segmentRaw .
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
  FILTER EXISTS {
    SELECT ?investorId
    WHERE {
      ?investor2 a wm:Investor ;
                 wm:investorId ?investorId ;
                 wm:hasScenarioRebalancing ?scenarioRebalancing2 .
      ?scenarioRebalancing2 a wm:ScenarioRebalancing .
    }
  }
  FILTER EXISTS {
    SELECT ?investorId
    WHERE {
      ?investor3 a wm:Investor ;
                 wm:investorId ?investorId ;
                 wm:hasInvestmentGoal ?investmentGoal3 .
      ?investmentGoal3 a wm:InvestmentGoal .
    }
  }
}
GROUP BY ?segment

