SELECT ?segment
  (AVG(xsd:decimal(?cfAmount)) AS ?cash_flow_net_amount)
  (AVG(xsd:decimal(?avgProgress)) AS ?goal_progress)
  (AVG(xsd:decimal(?avgShortfall)) AS ?shortfall)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cfAmount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgress) (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasSegment ?segmentObj .
  ?segmentObj wm:segment ?segmentRaw .
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
}
GROUP BY ?segment

