  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?targetAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?rebalancing_gap_val)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction wm:targetAllocationPct ?targetAllocationPct .
      ?rebalancingAction wm:currentAllocationPct ?currentAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?rebalancing_amount_val)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId .
  ?investor wm:riskTolerance ?riskToleranceRaw .
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
