PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor_category ?cash_flow_type (SUM(?pre_count) AS ?investor_count_with_rebalancing)
WHERE {
  {
    SELECT ?investorId ?investor_category_raw ?cash_flow_type_raw (COUNT(?investorId) AS ?pre_count)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:category ?investor_category_raw ;
                wm:hasCashFlow ?cashFlow .
      ?cashFlow a wm:CashFlow ;
                wm:type ?cash_flow_type_raw .
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction a wm:RebalancingAction .
    }
    GROUP BY ?investorId ?investor_category_raw ?cash_flow_type_raw
  }
  BIND(COALESCE(STR(?investor_category_raw), "NULL") AS ?investor_category)
  BIND(COALESCE(STR(?cash_flow_type_raw), "NULL") AS ?cash_flow_type)
}
GROUP BY ?investor_category ?cash_flow_type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
