SELECT ?risk_tolerance_group (SUM(xsd:decimal(?holdingCost)) AS ?total_2024_holding_purchases) (SUM(xsd:decimal(?cashFlowAmount)) AS ?total_2024_cash_flow_amounts)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cost)) AS ?holdingCost)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:purchaseDate ?purchaseDate .
      FILTER(CONTAINS(LCASE(STR(?purchaseDate)), "2024"))
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:date ?date .
      FILTER(CONTAINS(LCASE(STR(?date)), "2024"))
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:riskTolerance ?riskToleranceRaw . }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance_group)
}
GROUP BY ?risk_tolerance_group

