  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .
  FILTER NOT EXISTS { ?investor wm:hasCategory ?hasCategory . }
  FILTER NOT EXISTS { ?investor wm:hasCashFlow ?hasCashFlow . }
  FILTER NOT EXISTS { ?investor wm:hasHolding ?hasHolding . }
  FILTER NOT EXISTS { ?investor wm:hasPortfolioHealth ?hasPortfolioHealth . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
