PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category (AVG(xsd:decimal(?invAllocAvg)) AS ?avg_allocation_percentage) (AVG(xsd:decimal(?holdingReturnsAvg)) AS ?avg_holding_returns)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?allocPct)) AS ?invAllocAvg) (AVG(xsd:decimal(?returns)) AS ?holdingReturnsAvg)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPercentage ?allocPct .
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:returnsPct ?returns .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:category ?categoryRaw . }
  BIND(COALESCE(STR(?categoryRaw), "NULL") AS ?profile_category)
}
GROUP BY ?profile_category

