}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress) (SUM(xsd:decimal(?allocationPct)) AS ?sector_allocation) (AVG(xsd:decimal(?diversificationScore)) AS ?diversification_score)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:investorId ?investorId ;
                  wm:progressPct ?progressPct .
  ?sectorAllocation a wm:SectorAllocation ;
                    wm:investorId ?investorId ;
                    wm:allocationPct ?allocationPct .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:investorId ?investorId ;
                   wm:diversificationScore ?diversificationScore .
}
GROUP BY ?investorId
HAVING (AVG(xsd:decimal(?progressPct)) < 25 && SUM(xsd:decimal(?allocationPct)) > 40 && AVG(xsd:decimal(?diversificationScore)) < 30)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(?cashFlowSum) AS ?cash_flow)
       (AVG(?rebalancingAmountSum) AS ?rebalancing_amount)
       (AVG(?scenarioChangeAvg) AS ?scenario_change)
       (AVG(?riskScoreAvg) AS ?risk_score)
       (AVG(?goalMatchAvg) AS ?goal_match)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?rebalancingAmountSum)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPct)) AS ?scenarioChangeAvg)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasScenarioRebalancing ?scenarioRebalancing .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?riskScoreAvg)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?goalMatchPct)) AS ?goalMatchAvg)
    WHERE {
      ?investor wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress_pct) (AVG(xsd:decimal(?avgSharpeRatio)) AS ?avg_avg_sharpe_ratio) (AVG(xsd:decimal(?riskScore)) AS ?avg_risk_score)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:investorId ?investorId ;
                  wm:progressPct ?progressPct ;
                  wm:avgSharpeRatio ?avgSharpeRatio .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:investorId ?investorId ;
                   wm:riskScore ?riskScore .
}
GROUP BY ?investorId
HAVING (AVG(xsd:decimal(?progressPct)) < 40 && AVG(xsd:decimal(?avgSharpeRatio)) < 0 && AVG(xsd:decimal(?riskScore)) > 70)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?totalWithdrawal ?totalDeposit
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalWithdrawal)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:type ?type ;
                wm:amount ?amount .
      FILTER(LCASE(STR(?type)) = "withdrawal")
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalDeposit)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:type ?type ;
                wm:amount ?amount .
      FILTER(LCASE(STR(?type)) = "deposit")
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?sectorAlloc a wm:SectorAllocation ;
               wm:allocationOfInvestor ?investor ;
               wm:allocationPct ?allocationPct .
  FILTER(xsd:decimal(?allocationPct) > 20)
  ?scenarioReb a wm:ScenarioRebalancing ;
               wm:scenarioRebalancingOfInvestor ?investor ;
               wm:triggeredAction ?triggeredAction ;
               wm:scenario ?scenario .
  FILTER(LCASE(STR(?triggeredAction)) = "sell" && LCASE(STR(?scenario)) = "flash crash")
}
HAVING (?totalWithdrawal > ?totalDeposit)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cash_flow_type (SUM(?cfAmount) AS ?total_cash_flow_amount) (SUM(?raAmount) AS ?total_rebalancing_amount)
WHERE {
  {
    SELECT ?investorId ?cash_flow_type (SUM(xsd:decimal(?amount)) AS ?cfAmount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:hasCashFlowType ?cash_flow_type ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId ?cash_flow_type
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?raAmount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  FILTER EXISTS {
    ?cf2 a wm:CashFlow ;
         wm:investorId ?investorId .
  }
  FILTER EXISTS {
    ?ra2 a wm:RebalancingAction ;
         wm:investorId ?investorId .
  }
}
GROUP BY ?cash_flow_type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasInvestmentGoal ?investmentGoal ;
            wm:hasPortfolioHealth ?portfolioHealth ;
            wm:hasCashFlow ?cashFlow .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:investmentGoal ?goal .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:liquidityScore ?liquidityScore .
  ?cashFlow a wm:CashFlow ;
            wm:type ?type .
  FILTER(LCASE(STR(?goal)) = "emergency fund")
  FILTER(xsd:decimal(?liquidityScore) > 70)
  FILTER(LCASE(STR(?type)) = "withdrawal")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)
  ?portfolioHolding a wm:PortfolioHolding ;
                    wm:heldByInvestor ?investor ;
                    wm:returnsPct ?returnsPct .
  FILTER(xsd:decimal(?returnsPct) < 0)
  ?sectorAllocation a wm:SectorAllocation ;
                    wm:allocationOfInvestor ?investor ;
                    wm:allocationPct ?allocationPct .
  FILTER(xsd:decimal(?allocationPct) > 25)
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:healthOfInvestor ?investor ;
                   wm:diversificationScore ?diversificationScore .
  FILTER(xsd:decimal(?diversificationScore) < 40)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  (COUNT(DISTINCT ?investor) AS ?investors_with_segment_in_holding)
  (COUNT(DISTINCT ?investorNoMatch) AS ?investors_without_segment_in_holding)
WHERE {
  {
    SELECT DISTINCT ?investor
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:segment ?investorSegment .
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:segment ?holdingSegment .
      FILTER(?investorSegment = ?holdingSegment)
    }
  }
  {
    SELECT DISTINCT ?investorNoMatch
    WHERE {
      ?investorNoMatch a wm:Investor .
      ?investorNoMatch wm:segment ?investorSegment .
      FILTER NOT EXISTS {
        ?holding a wm:PortfolioHolding .
        ?holding wm:heldByInvestor ?investorNoMatch .
        ?holding wm:segment ?holdingSegment .
        FILTER(?investorSegment = ?holdingSegment)
      }
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(COALESCE(xsd:decimal(?amount), 0)) + SUM(COALESCE(xsd:decimal(?rebalanceAmount), 0)) - SUM(COALESCE(xsd:decimal(?shortfall), 0)) + SUM(COALESCE(xsd:decimal(?newAllocationPct), 0)) AS ?temporal_pressure_score)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  OPTIONAL {
    ?investor wm:hasCashFlow ?cashFlow .
    ?cashFlow wm:amount ?amount .
  }
  OPTIONAL {
    ?investor wm:hasRebalancingAction ?rebalancingAction .
    ?rebalancingAction wm:amount ?rebalanceAmount .
  }
  OPTIONAL {
    ?investor wm:hasInvestmentGoal ?investmentGoal .
    ?investmentGoal wm:shortfall ?shortfall .
  }
  OPTIONAL {
    ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
    ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
  }
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?temporal_pressure_score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?net_cash_flow ?avg_goal_progress ?risk_score ?scenario_change
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?investor a wm:Investor .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress)
    WHERE {
      ?investor a wm:Investor .
      ?investmentGoal wm:belongsToInvestor ?investor ;
                      wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?riskScore)) AS ?risk_score)
    WHERE {
      ?investor a wm:Investor .
      ?portfolioHealth wm:healthOfInvestor ?investor ;
                       wm:riskScore ?riskScore .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?newAllocationPct)) AS ?scenario_change)
    WHERE {
      ?investor a wm:Investor .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investor
  }
  ?investor wm:investorId ?investorId .
  FILTER (xsd:decimal(?net_cash_flow) > 100000000 && xsd:decimal(?avg_goal_progress) < 25 && xsd:decimal(?risk_score) > 70 && xsd:decimal(?scenario_change) > 20)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category (AVG(?scenarioChangePerInvestor) AS ?scenario_change) (AVG(?goalProgressPerInvestor) AS ?goal_progress) (AVG(?volatilityPerInvestor) AS ?volatility)
WHERE {
  {
    SELECT ?investorId (COUNT(?scenarioRebalancing) AS ?scenarioChangePerInvestor) (AVG(xsd:decimal(?progressPct)) AS ?goalProgressPerInvestor) (AVG(xsd:decimal(?avgVolatilityPct)) AS ?volatilityPerInvestor)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL { ?scenarioRebalancing a wm:ScenarioRebalancing ; wm:scenarioRebalancingOfInvestor ?investor . }
      OPTIONAL { ?investmentGoal a wm:InvestmentGoal ; wm:belongsToInvestor ?investor ; wm:progressPct ?progressPct ; wm:avgVolatilityPct ?avgVolatilityPct . }
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category ?profile_categoryRaw .
  BIND(COALESCE(STR(?profile_categoryRaw), "NULL") AS ?profile_category)
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_group (SUM(?cnt1) AS ?count_1_goal) (SUM(?cnt2) AS ?count_2_goals) (SUM(?cnt3plus) AS ?count_3_or_more_goals)
WHERE {
  {
    SELECT ?investorId ?riskToleranceRaw 
           (COUNT(?investmentGoal) AS ?goalCount)
           (IF(COUNT(?investmentGoal) = 1, 1, 0) AS ?cnt1)
           (IF(COUNT(?investmentGoal) = 2, 1, 0) AS ?cnt2)
           (IF(COUNT(?investmentGoal) >= 3, 1, 0) AS ?cnt3plus)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL { ?investor wm:hasInvestmentGoal ?investmentGoal . }
      OPTIONAL { ?investor wm:riskTolerance ?riskToleranceRaw . }
    }
    GROUP BY ?investorId ?riskToleranceRaw
  }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance_group)
}
GROUP BY ?risk_tolerance_group

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (AVG(?avgGoalProgress) AS ?avg_goal_progress) (AVG(?avgLiquidityScore) AS ?avg_liquidity_score)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?goalMatchPct)) AS ?avgGoalProgress) (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:healthOfInvestor ?investor ;
                       wm:goalMatchPct ?goalMatchPct ;
                       wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
  ?sectorAllocation a wm:SectorAllocation ;
                    wm:investorId ?investorId ;
                    wm:sector ?sector .
}
GROUP BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon ?cash_flow_source (COUNT(?cashFlowId) AS ?cash_flow_count)
WHERE {
  ?cashFlow rdf:type wm:CashFlow .
  ?cashFlow wm:cashFlowId ?cashFlowId .
  OPTIONAL { ?cashFlow wm:hasCashFlowSource ?cashFlowSource . }
  OPTIONAL { ?cashFlowSource rdf:type wm:CashFlowSource . }
  OPTIONAL { ?cashFlow wm:hasCashFlowType ?cashFlowType . }
  OPTIONAL { ?cashFlowType rdf:type wm:TimeHorizon . }
  BIND(COALESCE(STR(?cashFlowSource), "NULL") AS ?cash_flow_source)
  BIND(COALESCE(STR(?cashFlowType), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon ?cash_flow_source

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_group (AVG(?scenarioCount) AS ?avg_scenario_change) (AVG(?goalProgress) AS ?avg_goal_progress) (AVG(?goalVolatility) AS ?avg_volatility)
WHERE {
  {
    SELECT ?investorId (COUNT(?scenario) AS ?scenarioCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:investorId ?investorId ;
                           wm:scenario ?scenario .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:investorId ?investorId ;
                      wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?avgVolatilityPct)) AS ?goalVolatility)
    WHERE {
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:investorId ?investorId ;
                      wm:avgVolatilityPct ?avgVolatilityPct .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskToleranceRaw .
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance_group)
}
GROUP BY ?risk_tolerance_group

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investorId) AS ?investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasHolding ?holding .
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:date ?date .
  FILTER (xsd:date(?date) >= xsd:date("2025-01-01") && xsd:date(?date) <= xsd:date("2025-12-31"))
  ?rebalancingAction a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor_category (SUM(?holdingGain) AS ?total_holding_gain) (AVG(?goalShortfall) AS ?average_goal_shortfall)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?holdingGain)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?goalShortfall)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category ?investor_category .
}
GROUP BY ?investor_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_group (AVG(?goal_progress) AS ?avg_goal_progress) (AVG(?risk_score) AS ?avg_risk_score) (SUM(?holding_value) AS ?total_holding_value)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goal_progress) (AVG(xsd:decimal(?riskScore)) AS ?risk_score) (SUM(xsd:decimal(?currentValue)) AS ?holding_value)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:belongsToInvestor ?investor ;
                      wm:progressPct ?progressPct .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:healthOfInvestor ?investor ;
                       wm:riskScore ?riskScore .
      ?portfolioHolding a wm:PortfolioHolding ;
                        wm:heldByInvestor ?investor ;
                        wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:riskTolerance ?riskToleranceRaw . }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance_group)
}
GROUP BY ?risk_tolerance_group

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_group (SUM(xsd:decimal(?holdingValue)) AS ?total_holding_value) (SUM(xsd:decimal(?sectorInvestment)) AS ?total_sector_allocation_investment)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?holdingValue)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding .
      ?holding wm:holdingValue ?holdingValue .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?sectorInvestment)
    WHERE {
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:investorId ?investorId ;
                   wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance wm:riskTolerance ?risk_tolerance_group .
}
GROUP BY ?risk_tolerance_group

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector ?total_holding_value ?total_recorded_sector_allocation_investment
WHERE {
  {
    SELECT ?sector (SUM(xsd:decimal(?currentValue)) AS ?total_holding_value)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:sector ?sector .
      ?holding wm:currentValue ?currentValue .
    }
    GROUP BY ?sector
  }
  {
    SELECT ?sector (SUM(xsd:decimal(?totalInvestment)) AS ?total_recorded_sector_allocation_investment)
    WHERE {
      ?allocation a wm:SectorAllocation .
      ?allocation wm:sector ?sector .
      ?allocation wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?sector
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  (SUM(IF(!BOUND(?investmentType), 1, 0)) AS ?missing_investment_type)
  (SUM(IF(!BOUND(?sector), 1, 0)) AS ?missing_sector)
  (SUM(IF(!BOUND(?segment), 1, 0)) AS ?missing_segment)
  (SUM(IF(!BOUND(?category), 1, 0)) AS ?missing_category)
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId .
  OPTIONAL { ?holding wm:investmentType ?investmentType . }
  OPTIONAL { ?holding wm:sector ?sector . }
  OPTIONAL { ?holding wm:segment ?segment . }
  OPTIONAL { ?holding wm:category ?category . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
  (AVG(?cashFlowNetAmount) AS ?cash_flow_net_amount)
  (AVG(?scenarioChange) AS ?scenario_change)
  (AVG(?scenarioCount) AS ?scenario_count)
WHERE {
  {
    SELECT ?investorId
      (SUM(xsd:decimal(?amount)) AS ?cashFlowNetAmount)
      (AVG(xsd:decimal(?newAllocationPct)) AS ?scenarioChange)
      (COUNT(?scenarioRebalanceId) AS ?scenarioCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct ;
                           wm:scenarioRebalanceId ?scenarioRebalanceId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:segment ?segmentRaw .
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?investor_total) AS ?monthly_net_cash_flow)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?investor_total)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow .
      ?cashFlow a wm:CashFlow ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance_raw .
  BIND(COALESCE(STR(?risk_tolerance_raw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:healthOfInvestor ?investor ;
                   wm:liquidityScore ?liquidityScore ;
                   wm:diversificationScore ?diversificationScore .
  FILTER (?liquidityScore < 25 && ?diversificationScore < 25)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (SUM(?rebalancingSum) AS ?total_rebalancing_amount) (SUM(?cashFlowSum) AS ?total_cash_flow) (SUM(?transactionCount) AS ?transaction_count)
WHERE {
  {
    SELECT ?investorId ?time_horizon (SUM(xsd:decimal(?amount)) AS ?rebalancingSum) (COUNT(?rebalanceId) AS ?transactionCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:timeHorizon ?time_horizon .
      ?timeHorizon a wm:TimeHorizon .
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:investorId ?investorId ;
                         wm:amount ?amount ;
                         wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?investorId ?time_horizon
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:investorId ?investorId ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasInvestmentGoal ?investmentGoal ;
            wm:hasScenarioRebalancing ?scenarioRebalancing .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:shortfall ?shortfall .
  ?scenarioRebalancing a wm:ScenarioRebalancing ;
                       wm:triggeredAction ?triggeredAction ;
                       wm:scenario ?scenario .
  FILTER (xsd:decimal(?shortfall) > 1000000)
  FILTER (LCASE(STR(?triggeredAction)) = "de-risking actions")
  FILTER (LCASE(STR(?scenario)) = "bear market")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profileCategory
       (AVG(xsd:decimal(?shortfall)) AS ?goalShortfall)
       (SUM(xsd:decimal(?currentValue)) AS ?holdingValue)
       (MAX(xsd:decimal(?allocationPct)) AS ?allocationConcentration)
       (AVG(xsd:decimal(?liquidityScore)) AS ?liquidity)
       (AVG(xsd:decimal(?diversificationScore)) AS ?diversification)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL {
    ?investor wm:profileCategory ?profileCategory .
  }
  ?goal a wm:InvestmentGoal ;
        wm:investorId ?investorId ;
        wm:shortfall ?shortfall .
  ?holding a wm:PortfolioHolding ;
           wm:investorId ?investorId ;
           wm:currentValue ?currentValue .
  ?alloc a wm:SectorAllocation ;
         wm:investorId ?investorId ;
         wm:allocationPct ?allocationPct .
  ?health a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?diversificationScore .
}
GROUP BY ?profileCategory
ORDER BY ?profileCategory

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?avg_goal_progress ?avg_health_risk ?avg_liquidity
WHERE {
  {
    SELECT ?investorId ?category
           (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress)
           (AVG(xsd:decimal(?riskScore)) AS ?avg_health_risk)
           (AVG(xsd:decimal(?liquidityScore)) AS ?avg_liquidity)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:category ?category .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:progressPct ?progressPct ;
                      wm:belongsToInvestor ?investor .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:riskScore ?riskScore ;
                       wm:liquidityScore ?liquidityScore ;
                       wm:healthOfInvestor ?investor .
    }
    GROUP BY ?investorId ?category
  }
}
GROUP BY ?category ?avg_goal_progress ?avg_health_risk ?avg_liquidity

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?total_holding_gain) (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:currentValue ?currentValue ;
           wm:cost ?cost .
  FILTER (xsd:decimal(?currentValue) > 0 && xsd:decimal(?cost) > 0)
  ?cashflow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amount .
}
GROUP BY ?investorId
HAVING (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) < 0 && SUM(xsd:decimal(?amount)) < 0)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?scenario_change_per_investor) AS ?scenario_change) (AVG(?rebalancing_gap_per_investor) AS ?rebalancing_gap) (AVG(?health_risk_per_investor) AS ?health_risk) (AVG(?goal_match_per_investor) AS ?goal_match)
WHERE {
  {
    SELECT ?investorId (COUNT(DISTINCT ?scenario) AS ?scenario_change_per_investor) (AVG(xsd:decimal(?newAllocationPct)) AS ?rebalancing_gap_per_investor)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:investorId ?investorId ;
                           wm:scenario ?scenario ;
                           wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?health_risk_per_investor) (AVG(xsd:decimal(?goalMatchPct)) AS ?goal_match_per_investor)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:investorId ?investorId ;
                       wm:riskScore ?riskScore ;
                       wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance_raw .
  BIND(COALESCE(STR(?risk_tolerance_raw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category
       (AVG(xsd:decimal(?cashFlowAmount)) AS ?cash_flow)
       (AVG(xsd:decimal(?scenarioNewAllocationPct)) AS ?scenario_change)
       (AVG(xsd:decimal(?allocationMaxPct)) AS ?allocation_concentration)
       (AVG(xsd:decimal(?sectorTotalInvestment)) AS ?sector_investment)
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?newAllocationPct)) AS ?scenarioNewAllocationPct)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (MAX(xsd:decimal(?allocationPct)) AS ?allocationMaxPct)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?sectorAllocation wm:allocationOfInvestor ?investor ;
                        wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?totalInvestment)) AS ?sectorTotalInvestment)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?sectorAllocation wm:allocationOfInvestor ?investor ;
                        wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:category ?profile_category .
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?avgProgressPct) AS ?avg_goal_progress) (AVG(?avgRiskScore) AS ?avg_health_risk) (AVG(?avgLiquidityScore) AS ?avg_liquidity)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPctRaw)) AS ?avgProgressPct)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:progressPct ?progressPctRaw .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScoreRaw)) AS ?avgRiskScore) (AVG(xsd:decimal(?liquidityScoreRaw)) AS ?avgLiquidityScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:riskScore ?riskScoreRaw ;
                       wm:liquidityScore ?liquidityScoreRaw .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskToleranceRaw .
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
