  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?riskTolerance_group)
  ?investor wm:hasHolding ?holding .
  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?investmentTypeNode .
  OPTIONAL { ?investmentTypeNode rdfs:label ?investmentTypeRaw . }
  BIND(COALESCE(STR(?investmentTypeRaw), "NULL") AS ?investmentType_group)
}
