PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (SUM(xsd:decimal(?inflowAmount)) AS ?total_inflow) (SUM(xsd:decimal(?outflowAmount)) AS ?total_outflow)
WHERE {
  {
    SELECT ?investorId ?timeHorizon (SUM(xsd:decimal(?inflowPart)) AS ?inflowAmount) (SUM(xsd:decimal(?outflowPart)) AS ?outflowAmount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasTimeHorizon ?timeHorizon .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:type ?type ;
                wm:amount ?amount .
      BIND(IF(LCASE(STR(?type)) = "inflow", xsd:decimal(?amount), 0) AS ?inflowPart)
      BIND(IF(LCASE(STR(?type)) = "outflow", xsd:decimal(?amount), 0) AS ?outflowPart)
    }
    GROUP BY ?investorId ?timeHorizon
  }
  OPTIONAL { ?timeHorizon wm:timeHorizon ?time_horizon_raw . }
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

