SELECT ?time_horizon (SUM(?investor_cash_flow) AS ?cash_flow_net_amount) (SUM(?investor_scenario_change) AS ?scenario_change) (COUNT(?investor_scenario_count) AS ?scenario_count)
WHERE {
  {
    SELECT ?investorId ?timeHorizonRaw (SUM(xsd:decimal(?amount)) AS ?investor_cash_flow) (COUNT(?scenarioRebalancing) AS ?investor_scenario_change) (COUNT(?scenarioRebalancing) AS ?investor_scenario_count)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizonRaw . }
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
      OPTIONAL { ?investor wm:hasScenarioRebalancing ?scenarioRebalancing . }
    }
    GROUP BY ?investorId ?timeHorizonRaw
  }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
} GROUP BY ?time_horizon

