                   wm:diversificationScore ?diversificationScore .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:investorId ?investorId ;
                  wm:progressPct ?progressPct .
}
GROUP BY ?investorId
HAVING (AVG(xsd:decimal(?riskScore) + (100 - xsd:decimal(?liquidityScore)) + (100 - xsd:decimal(?diversificationScore))) > 220
        && AVG(xsd:decimal(?progressPct)) < 40)

