    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?sectorInvestment)
    WHERE {
      ?allocation a wm:SectorAllocation ;
                  wm:investorId ?investorId ;
                  wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  ?holding a wm:PortfolioHolding ;
           wm:investorId ?investorId ;
           wm:category ?categoryRaw .
  BIND(COALESCE(STR(?categoryRaw), "NULL") AS ?portfolio_risk_band)
}
