      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investmentGoal wm:investorId ?investorId ;
                  wm:investmentGoal ?investment_goal .
  ?investor2 wm:investorId ?investorId .
