SELECT ?time_horizon (AVG(?allocPctAvg) AS ?allocation_concentration) (AVG(?returnsPctAvg) AS ?holding_return) (SUM(?currentValueSum) AS ?holding_value)
WHERE {
  {
    SELECT ?investorId ?timeHorizonRaw (AVG(xsd:decimal(?allocPct)) AS ?allocPctAvg) (AVG(xsd:decimal(?returnsPct)) AS ?returnsPctAvg) (SUM(xsd:decimal(?currentValue)) AS ?currentValueSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:timeHorizon ?timeHorizonRaw .
      ?investor wm:hasHolding ?holding .
      ?holding a wm:PortfolioHolding ;
               wm:returnsPct ?returnsPct ;
               wm:currentValue ?currentValue .
      ?investor wm:hasSectorAllocation ?sectorAlloc .
      ?sectorAlloc a wm:SectorAllocation ;
                   wm:allocationPct ?allocPct .
    }
    GROUP BY ?investorId ?timeHorizonRaw
  }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?total_goal_shortfall ?net_cash_flow
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_goal_shortfall) (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
      ?action a wm:RebalancingAction ;
              wm:rebalancingActionOfInvestor ?investor ;
              wm:action ?actionValue .
      FILTER(LCASE(STR(?actionValue)) = "de-risking")
    }
    GROUP BY ?investorId
  }
  FILTER(?total_goal_shortfall > 0 && ?net_cash_flow < 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_value (AVG(?inv_allocation_concentration) AS ?allocation_concentration) (AVG(?inv_holding_return) AS ?holding_return) (AVG(?inv_holding_value) AS ?holding_value)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?inv_allocation_concentration) (AVG(xsd:decimal(?returnsPct)) AS ?inv_holding_return) (SUM(xsd:decimal(?currentValue)) AS ?inv_holding_value) ?risk_tolerance_value
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding ;
                wm:hasRiskTolerance ?riskTolerance .
      ?holding a wm:PortfolioHolding ;
               wm:currentValue ?currentValue ;
               wm:returnsPct ?returnsPct .
      ?riskTolerance a wm:RiskTolerance ;
                     wm:riskTolerance ?riskToleranceValueRaw .
      BIND(COALESCE(STR(?riskToleranceValueRaw), "NULL") AS ?risk_tolerance_value)
    }
    GROUP BY ?investorId ?risk_tolerance_value
  }
}
GROUP BY ?risk_tolerance_value

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor_id ?avg_sharpe_ratio ?avg_volatility_pct ?total_holding_gain ?net_cash_flow
WHERE {
  {
    SELECT ?investor_id (AVG(xsd:decimal(?avgSharpeRatio)) AS ?avg_sharpe_ratio) (AVG(xsd:decimal(?avgVolatilityPct)) AS ?avg_volatility_pct) (SUM(xsd:decimal(?shortfall)) AS ?total_holding_gain)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investor_id .
      ?investor wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal wm:avgSharpeRatio ?avgSharpeRatio .
      ?investmentGoal wm:avgVolatilityPct ?avgVolatilityPct .
      ?investmentGoal wm:shortfall ?shortfall .
    }
    GROUP BY ?investor_id
  }
  {
    SELECT ?investor_id (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investor_id .
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investor_id
  }
  FILTER(?avg_sharpe_ratio < 0 && ?avg_volatility_pct > 10 && ?total_holding_gain < 0 && ?net_cash_flow < 1000000)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?net_cash_flow ?rebalancing_amount ?scenario_allocation_change ?score
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?rebalancing_amount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?newAllocationPct)) AS ?scenario_allocation_change)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .
  BIND(?net_cash_flow + ?rebalancing_amount + ?scenario_allocation_change AS ?score)
}
ORDER BY DESC(?score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
