SELECT (COUNT(?investorId) AS ?investor_count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:type ?type .
  FILTER(LCASE(STR(?type)) = "sip")
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:investmentGoal ?goal .
  FILTER(LCASE(STR(?goal)) = "growth")
  ?rebalancingAction a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor ;
                     wm:logic ?logic .
  FILTER(LCASE(STR(?logic)) = "momentum-driven")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
