}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?cashFlowSum) AS ?cash_flow_net_amount) (AVG(?progressAvg) AS ?goal_progress) (AVG(?shortfallAvg) AS ?shortfall)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?progressAvg) (AVG(xsd:decimal(?shortfall)) AS ?shortfallAvg)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?investmentGoal wm:belongsToInvestor ?investor ;
                      wm:progressPct ?progressPct ;
                      wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
