PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_group (AVG(?inv_avg_shortfall) AS ?avg_goal_shortfall) (AVG(?inv_avg_health) AS ?avg_portfolio_health_score)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?inv_avg_shortfall) (AVG(xsd:decimal(?goalMatchPct)) AS ?inv_avg_health)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?investmentGoal ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?investmentGoal wm:shortfall ?shortfall .
      ?portfolioHealth wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?riskTolerance .
    ?riskTolerance wm:riskTolerance ?riskToleranceRaw .
  }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance_group)
}
GROUP BY ?risk_tolerance_group

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
