SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:type ?type .
  FILTER(LCASE(STR(?type)) = "withdrawal")
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:timeToGoalMonths ?timeToGoalMonths .
  FILTER(xsd:decimal(?timeToGoalMonths) <= 12)
  ?rebalancingAction a wm:RebalancingAction ;
                     wm:rebalancingActionOfInvestor ?investor ;
                     wm:action ?action .
  FILTER(LCASE(STR(?action)) = "rebalance sell")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:healthOfInvestor ?investor ;
                   wm:riskScore ?riskScore ;
                   wm:diversificationScore ?diversificationScore .
  ?sectorAllocation a wm:SectorAllocation ;
                    wm:allocationOfInvestor ?investor ;
                    wm:allocationPct ?allocationPct .
  ?portfolioHolding a wm:PortfolioHolding ;
                    wm:heldByInvestor ?investor ;
                    wm:returnsPct ?returnsPct .
  FILTER (xsd:decimal(?riskScore) > 100)
  FILTER (xsd:decimal(?diversificationScore) < 30)
  FILTER (xsd:decimal(?allocationPct) > 35)
  FILTER (xsd:decimal(?returnsPct) < 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskTolerance ;
            wm:hasInvestmentGoal ?investmentGoal ;
            wm:hasHolding ?portfolioHolding .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:shortfall ?shortfall .
  ?portfolioHolding a wm:PortfolioHolding ;
                    wm:investmentName ?investmentName .
  FILTER(LCASE(STR(?riskTolerance)) = "aggressive")
  FILTER(xsd:decimal(?shortfall) > 0)
  FILTER(CONTAINS(LCASE(STR(?investmentName)), "gold"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?invProgress) AS ?avg_goal_progress) (AVG(?invShortfall) AS ?avg_shortfall)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?invProgress) (AVG(xsd:decimal(?shortfall)) AS ?invShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct ;
            wm:shortfall ?shortfall .
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasRiskTolerance ?riskTolerance .
  ?riskTolerance a wm:RiskTolerance .
  OPTIONAL { ?riskTolerance rdfs:label ?risk_tolerance_raw . }
  BIND(COALESCE(STR(?risk_tolerance_raw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goal_context (AVG(xsd:decimal(?investorAvgProgress)) AS ?average_progress)
WHERE {
  {
    SELECT ?investorId ?goal_context (AVG(xsd:decimal(?progressPct)) AS ?investorAvgProgress)
    WHERE {
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:investmentGoal ?goal_context ;
                      wm:progressPct ?progressPct ;
                      wm:investorId ?investorId .
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:riskTolerance ?riskTolerance .
      FILTER(LCASE(STR(?riskTolerance)) = "aggressive")
    }
    GROUP BY ?investorId ?goal_context
  }
}
GROUP BY ?goal_context
ORDER BY DESC(?average_progress) ?goal_context
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
