PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasInvestmentGoal ?goal .
  ?goal a wm:InvestmentGoal ;
        wm:progressPct ?progressPct .
  ?investor wm:hasPortfolioHealth ?health .
  ?health a wm:PortfolioHealth ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore .
  FILTER (xsd:decimal(?progressPct) < 20)
  FILTER (xsd:decimal(?riskScore) < 30)
  FILTER (xsd:decimal(?liquidityScore) < 30)
}
GROUP BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?group_value (AVG(?goal_progress_val) AS ?goal_progress) (AVG(?holding_gain_val) AS ?holding_gain) (AVG(?risk_score_val) AS ?risk_score) (AVG(?liquidity_val) AS ?liquidity)
WHERE {
  {
    SELECT ?investorId 
           (AVG(xsd:decimal(?progressPct)) AS ?goal_progress_val)
           (AVG(xsd:decimal(?returnsPct)) AS ?holding_gain_val)
           (AVG(xsd:decimal(?riskScore)) AS ?risk_score_val)
           (AVG(xsd:decimal(?liquidityScore)) AS ?liquidity_val)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:investorId ?investorId ;
                      wm:progressPct ?progressPct .
      ?portfolioHolding a wm:PortfolioHolding ;
                        wm:investorId ?investorId ;
                        wm:returnsPct ?returnsPct .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:investorId ?investorId ;
                       wm:riskScore ?riskScore ;
                       wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:category ?group_value .
}
GROUP BY ?group_value

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_group (SUM(xsd:decimal(?depositAmount)) AS ?total_deposit_amount) (SUM(xsd:decimal(?rebalancingAmount)) AS ?total_rebalancing_amount)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?depositAmount)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?rebalancingAmount)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?rebalancingAction wm:rebalancingActionOfInvestor ?investor ;
                         wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:riskTolerance ?riskToleranceRaw . }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance_group)
}
GROUP BY ?risk_tolerance_group

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
