PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?holding_gain_sum) AS ?holding_gain) (AVG(?health_risk_avg) AS ?health_risk) (AVG(?diversification_avg) AS ?diversification)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?holding_gain_sum)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasHolding ?holding .
      ?holding wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?health_risk_avg) (AVG(xsd:decimal(?diversificationScore)) AS ?diversification_avg)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:hasPortfolioHealth ?health .
      ?health wm:riskScore ?riskScore .
      ?health wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizonRaw . }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?cash_flow_sum) AS ?cash_flow) (AVG(?scenario_change_avg) AS ?scenario_change) (AVG(?allocation_concentration_max) AS ?allocation_concentration) (SUM(?sector_investment_sum) AS ?sector_investment)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cash_flow_sum)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPct)) AS ?scenario_change_avg)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (MAX(xsd:decimal(?allocationPct)) AS ?allocation_concentration_max)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?sectorAllocation wm:allocationOfInvestor ?investor .
      ?sectorAllocation wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?sector_investment_sum)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?sectorAllocation wm:allocationOfInvestor ?investor .
      ?sectorAllocation wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:timeHorizon ?time_horizon_raw . }
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (?totalShortfall - ?totalHoldingGain - ?netCashFlow + ?riskPressureScore AS ?quantitative_burden_score)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .
  OPTIONAL {
    ?investor wm:hasPortfolioHealth ?portfolioHealth .
    ?portfolioHealth wm:shortfall ?shortfall .
  }
  OPTIONAL {
    ?investor wm:hasHolding ?portfolioHolding .
    ?portfolioHolding wm:holdingGain ?holdingGain .
  }
  OPTIONAL {
    ?investor wm:hasCashFlow ?cashFlow .
    ?cashFlow wm:amount ?amount .
  }
  OPTIONAL {
    ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
    ?scenarioRebalancing wm:riskPressureScore ?riskPressureScore .
  }
}
GROUP BY ?investorId ?investorName
HAVING (SUM(xsd:decimal(?shortfall)) IS NOT NULL || SUM(xsd:decimal(?holdingGain)) IS NOT NULL || SUM(xsd:decimal(?amount)) IS NOT NULL || SUM(xsd:decimal(?riskPressureScore)) IS NOT NULL)
ORDER BY DESC(?quantitative_burden_score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profileCategory
       (AVG(?cashFlowSum) AS ?cashFlow)
       (AVG(?rebalancingAmountSum) AS ?rebalancingAmount)
       (AVG(?scenarioChangeCount) AS ?scenarioChange)
       (AVG(?riskScoreAvg) AS ?riskScore)
       (AVG(?goalMatchAvg) AS ?goalMatch)
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:investorId ?investorId ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?rebalancingAmountSum)
    WHERE {
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:investorId ?investorId ;
                         wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (COUNT(?scenarioRebalancing) AS ?scenarioChangeCount)
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?riskScore)) AS ?riskScoreAvg)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:investorId ?investorId ;
                       wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?goalMatchPct)) AS ?goalMatchAvg)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:investorId ?investorId ;
                       wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:investorId ?investorId ;
                   wm:profileCategory ?profileCategory .
}
GROUP BY ?profileCategory

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasHolding ?holding .
  ?holding a wm:PortfolioHolding ;
           wm:returnsPct ?returnsPct .
  FILTER (xsd:decimal(?returnsPct) < -20)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?avg_goal_progress ?total_withdrawal ?total_deposit ?sell_action_count
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress)
           (SUM(IF(xsd:decimal(?amount) > 0, xsd:decimal(?amount), 0)) AS ?total_withdrawal)
           (SUM(IF(xsd:decimal(?amount) < 0, xsd:decimal(?amount), 0)) AS ?total_deposit_raw)
           (COUNT(DISTINCT ?actionObj) AS ?sell_action_count)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL {
        ?investor wm:hasInvestmentGoal ?goal .
        ?goal a wm:InvestmentGoal ;
              wm:progressPct ?progressPct .
      }
      OPTIONAL {
        ?investor wm:hasCashFlow ?cashFlow .
        ?cashFlow a wm:CashFlow ;
                  wm:amount ?amount .
      }
      OPTIONAL {
        ?investor wm:hasRebalancingAction ?actionObj .
        ?actionObj a wm:RebalancingAction ;
                   wm:action ?action .
        FILTER (LCASE(STR(?action)) = "sell")
      }
    }
    GROUP BY ?investorId
  }
  BIND(xsd:decimal(?total_deposit_raw) * -1 AS ?total_deposit)
  ?investor wm:hasRiskTolerance ?riskToleranceObj .
  ?riskToleranceObj a wm:RiskTolerance ;
                    wm:riskTolerance ?riskToleranceVal .
  BIND(xsd:decimal(?riskToleranceVal) AS ?riskToleranceDec)
  FILTER (?avg_goal_progress < 30)
  FILTER (?riskToleranceDec > 60)
  FILTER (?total_withdrawal > ?total_deposit)
  FILTER (?sell_action_count >= 1)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holding_sector (COUNT(DISTINCT ?investorId) AS ?distinct_investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId ?sectorRaw
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
      FILTER(xsd:decimal(?riskScore) > 70)
      ?investor wm:hasHolding ?holding .
      ?holding a wm:PortfolioHolding ;
               wm:sector ?sectorRaw ;
               wm:returnsPct ?returnsPct .
      FILTER(xsd:decimal(?returnsPct) < 0)
    }
  }
  BIND(COALESCE(STR(?sectorRaw), "NULL") AS ?holding_sector)
}
GROUP BY ?holding_sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (COUNT(?holdingId) AS ?pharma_holdings) (SUM(xsd:decimal(?allocationPct)) AS ?pharma_allocation) ?diversification_score
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:sector ?sector ;
           wm:holdingId ?holdingId .
  FILTER(LCASE(STR(?sector)) = "pharma")
  ?health a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:diversificationScore ?diversification_score .
  FILTER(xsd:decimal(?diversification_score) < 40)
  ?allocation a wm:SectorAllocation ;
              wm:allocationOfInvestor ?investor ;
              wm:sector ?sectorAlloc ;
              wm:allocationPct ?allocationPct .
  FILTER(LCASE(STR(?sectorAlloc)) = "pharma")
}
GROUP BY ?investorId ?diversification_score

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?rebalancingAmountSum) AS ?rebalancing_amount) (AVG(?cashFlowSum) AS ?cash_flow) (AVG(?goalProgressAvg) AS ?goal_progress) (AVG(?shortfallAvg) AS ?shortfall)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?rebalancingAmountSum)
    WHERE {
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction wm:amount ?amount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goalProgressAvg) (AVG(xsd:decimal(?shortfall)) AS ?shortfallAvg)
    WHERE {
      ?investor wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal wm:progressPct ?progressPct .
      ?investmentGoal wm:shortfall ?shortfall .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId .
  ?investor wm:timeHorizon ?timeHorizonRaw .
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?goalContext (COUNT(?investorId) AS ?investorCount)
WHERE {
  {
    SELECT ?investorId ?timeHorizonRaw ?goalContextRaw
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizonRaw . }
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfallRaw ;
            wm:investmentGoal ?goalContextRaw .
      FILTER(xsd:decimal(?shortfallRaw) > 0)
    }
    GROUP BY ?investorId ?timeHorizonRaw ?goalContextRaw
  }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?timeHorizon)
  BIND(COALESCE(STR(?goalContextRaw), "NULL") AS ?goalContext)
}
GROUP BY ?timeHorizon ?goalContext

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (SUM(xsd:decimal(?rebalancingAmount)) AS ?total_rebalancing_amount)
       (SUM(xsd:decimal(?cashFlowAmount)) AS ?total_cash_flow)
       (SUM(?rebalancingCount) AS ?transaction_count)
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?rebalancingAmount)
           (COUNT(?rebalanceId) AS ?rebalancingCount)
    WHERE {
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:investorId ?investorId ;
                         wm:amount ?amount ;
                         wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?amount)) AS ?cashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:investorId ?investorId ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId ?segmentRaw
    WHERE {
      ?portfolioHolding a wm:PortfolioHolding ;
                        wm:investorId ?investorId ;
                        wm:segment ?segmentRaw .
    }
  }
  FILTER EXISTS {
    ?rebalancingAction2 a wm:RebalancingAction ;
                        wm:investorId ?investorId .
  }
  FILTER EXISTS {
    ?cashFlow2 a wm:CashFlow ;
               wm:investorId ?investorId .
  }
  FILTER EXISTS {
    ?portfolioHolding2 a wm:PortfolioHolding ;
                       wm:investorId ?investorId .
  }
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category (AVG(?inv_cash_flow_sum) AS ?cash_flow_net_amount) (AVG(?inv_goal_progress_avg) AS ?goal_progress) (AVG(?inv_shortfall_avg) AS ?shortfall)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?inv_cash_flow_sum)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?inv_goal_progress_avg) (AVG(xsd:decimal(?shortfall)) AS ?inv_shortfall_avg)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:category ?categoryRaw . }
  BIND(COALESCE(STR(?categoryRaw), "NULL") AS ?profile_category)
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?cashFlowSum) AS ?cash_flow_net_amount) (AVG(?scenarioCount) AS ?scenario_change) (AVG(?scenarioRebalanceIdCount) AS ?scenario_count)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (COUNT(?scenario) AS ?scenarioCount) (COUNT(?scenarioRebalanceId) AS ?scenarioRebalanceIdCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:scenario ?scenario ;
                           wm:scenarioRebalanceId ?scenarioRebalanceId .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?risk_score)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:investorId ?investorId ;
                   wm:goalMatchPct ?goalMatchPct ;
                   wm:riskScore ?riskScore .
  ?portfolioHolding a wm:PortfolioHolding ;
                    wm:investorId ?investorId ;
                    wm:returnsPct ?returnsPct .
  FILTER (xsd:decimal(?goalMatchPct) < 100)
  FILTER (xsd:decimal(?returnsPct) < 0)
}
GROUP BY ?investorId
ORDER BY DESC(?risk_score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?sharpeAvg) AS ?avg_sharpe_ratio) (AVG(?volAvg) AS ?avg_volatility_pct)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?sharpe)) AS ?sharpeAvg) (AVG(xsd:decimal(?vol)) AS ?volAvg)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?goal .
      ?goal a wm:InvestmentGoal ;
            wm:avgSharpeRatio ?sharpe ;
            wm:avgVolatilityPct ?vol .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskToleranceRaw .
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
