PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:type ?type .
  FILTER(LCASE(STR(?type)) = "redemption")
  ?scenarioRebalancing a wm:ScenarioRebalancing ;
                       wm:scenarioRebalancingOfInvestor ?investor ;
                       wm:triggeredAction ?triggeredAction ;
                       wm:scenario ?scenario .
  FILTER(LCASE(STR(?triggeredAction)) = "manual override")
  FILTER(LCASE(STR(?scenario)) = "flash crash")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (AVG(?goal_shortfall) AS ?goal_shortfall)
       (AVG(?holding_value) AS ?holding_value)
       (AVG(?allocation_concentration) AS ?allocation_concentration)
       (AVG(?liquidity) AS ?liquidity)
       (AVG(?diversification) AS ?diversification)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?shortfall)) AS ?goal_shortfall)
           (SUM(xsd:decimal(?currentValue)) AS ?holding_value)
           (MAX(xsd:decimal(?allocationPct)) AS ?allocation_concentration)
           (AVG(xsd:decimal(?liquidityScore)) AS ?liquidity)
           (AVG(xsd:decimal(?diversificationScore)) AS ?diversification)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:shortfall ?shortfall ;
                      wm:belongsToInvestor ?investor .
      ?portfolioHolding a wm:PortfolioHolding ;
                        wm:currentValue ?currentValue ;
                        wm:heldByInvestor ?investor .
      ?sectorAllocation a wm:SectorAllocation ;
                        wm:allocationPct ?allocationPct ;
                        wm:allocationOfInvestor ?investor .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:liquidityScore ?liquidityScore ;
                       wm:diversificationScore ?diversificationScore ;
                       wm:healthOfInvestor ?investor .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:timeHorizon ?timeHorizonRaw .
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon
ORDER BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?allocPctAvg) AS ?allocation_concentration)
       (AVG(?returnAvg) AS ?holding_return)
       (SUM(?valueSum) AS ?holding_value)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?allocPct)) AS ?allocPctAvg)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?return)) AS ?returnAvg)
           (SUM(xsd:decimal(?value)) AS ?valueSum)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:returnsPct ?return ;
          wm:currentValue ?value .
    }
    GROUP BY ?investorId
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:category ?categoryRaw .
  BIND(COALESCE(STR(?categoryRaw), "NULL") AS ?category)
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?investor_net_cash_flow) AS ?net_cash_flow) (AVG(?investor_avg_progress_pct) AS ?average_goal_progress_pct)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance_raw .
  BIND(COALESCE(STR(?risk_tolerance_raw), "NULL") AS ?risk_tolerance)
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?investor_net_cash_flow)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?investor_avg_progress_pct)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (SUM(?profileCount) AS ?profile_segment_count) (SUM(?holdingCount) AS ?holding_segment_count)
WHERE {
  {
    SELECT ?investorId ?segment (COUNT(?investorId) AS ?profileCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:segment ?segment .
    }
    GROUP BY ?investorId ?segment
  }
  UNION
  {
    SELECT ?investorId ?segment (COUNT(?holdingId) AS ?holdingCount)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:segment ?segment .
    }
    GROUP BY ?investorId ?segment
  }
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor_category (SUM(?depositSum) AS ?deposit_amount) (SUM(-?withdrawalSum) AS ?withdrawal_amount)
WHERE {
  {
    SELECT ?investorId ?category 
           (SUM(IF(?type != "Withdrawal", xsd:decimal(?amount), 0)) AS ?depositSum)
           (SUM(IF(?type = "Withdrawal", xsd:decimal(?amount), 0)) AS ?withdrawalSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:category ?category ;
                wm:hasCashFlow ?cashFlow .
      ?cashFlow a wm:CashFlow ;
                wm:amount ?amount ;
                wm:type ?type .
    }
    GROUP BY ?investorId ?category
  }
}
GROUP BY ?investor_category
ORDER BY ?investor_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (AVG(?holdingGainSum) AS ?holding_gain)
       (AVG(?healthRiskAvg) AS ?health_risk)
       (AVG(?diversificationAvg) AS ?diversification)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?holdingGainSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding .
      ?holding a wm:PortfolioHolding ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?healthRiskAvg)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?health .
      ?health a wm:PortfolioHealth ;
              wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?diversificationScore)) AS ?diversificationAvg)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?health .
      ?health a wm:PortfolioHealth ;
              wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:segment ?segmentRaw .
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (AVG(xsd:decimal(?maxAllocationPct)) AS ?allocation_concentration)
WHERE {
  {
    SELECT ?investorId (MAX(xsd:decimal(?allocationPct)) AS ?maxAllocationPct)
    WHERE {
      ?investor wm:investorId ?investorId .
      ?sectorAllocation wm:allocationOfInvestor ?investor ;
                        wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId ;
            wm:category ?category .
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(?goal_shortfall) AS ?goal_shortfall)
       (AVG(?holding_value) AS ?holding_value)
       (AVG(?allocation_concentration) AS ?allocation_concentration)
       (AVG(?liquidity) AS ?liquidity)
       (AVG(?diversification) AS ?diversification)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?shortfall)) AS ?goal_shortfall)
           (SUM(xsd:decimal(?currentValue)) AS ?holding_value)
           (MAX(xsd:decimal(?allocationPct)) AS ?allocation_concentration)
           (AVG(xsd:decimal(?liquidityScore)) AS ?liquidity)
           (AVG(xsd:decimal(?diversificationScore)) AS ?diversification)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:shortfall ?shortfall ;
                      wm:belongsToInvestor ?investor .
      ?portfolioHolding a wm:PortfolioHolding ;
                        wm:currentValue ?currentValue ;
                        wm:heldByInvestor ?investor .
      ?sectorAllocation a wm:SectorAllocation ;
                        wm:allocationPct ?allocationPct ;
                        wm:allocationOfInvestor ?investor .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:liquidityScore ?liquidityScore ;
                       wm:diversificationScore ?diversificationScore ;
                       wm:healthOfInvestor ?investor .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?scenario_change_val) AS ?scenario_change) (AVG(?rebalancing_gap_val) AS ?rebalancing_gap) (AVG(?health_risk_val) AS ?health_risk) (AVG(?goal_match_val) AS ?goal_match)
WHERE {
  {
    SELECT ?investorId (COUNT(DISTINCT ?scenario) AS ?scenario_change_val) (AVG(xsd:decimal(?newAllocationPct)) AS ?rebalancing_gap_val)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasScenarioRebalancing ?scenarioRebalancing .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenario ?scenario ;
                           wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?health_risk_val) (AVG(xsd:decimal(?goalMatchPct)) AS ?goal_match_val)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:riskScore ?riskScore ;
                       wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal a wm:InvestmentGoal .
    }
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:timeHorizon ?time_horizon_raw .
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario (AVG(?avgShortfallPerGoal) AS ?avg_shortfall)
WHERE {
  {
    SELECT ?goalId (AVG(xsd:decimal(?shortfall)) AS ?avgShortfallPerGoal) ?sourceTableRaw
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:goalId ?goalId ;
            wm:shortfall ?shortfall ;
            wm:sourceTable ?sourceTableRaw .
    }
    GROUP BY ?goalId ?sourceTableRaw
  }
  BIND(COALESCE(STR(?sourceTableRaw), "NULL") AS ?scenario)
}
GROUP BY ?scenario

