SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:type ?type ;
            wm:cashFlowOfInvestor ?investor .
  FILTER(LCASE(STR(?type)) = "tax refund")
  ?scenarioRebalancing a wm:ScenarioRebalancing ;
                       wm:scenario ?scenario ;
                       wm:scenarioRebalancingOfInvestor ?investor .
  FILTER(LCASE(STR(?scenario)) = "interest rate hike")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?scenario_change) AS ?scenario_change) (AVG(?goal_progress) AS ?goal_progress) (AVG(?volatility) AS ?volatility)
WHERE {
  {
    SELECT ?investorId ?timeHorizonRaw (COUNT(?scenarioRebalancing) AS ?scenario_change) (AVG(xsd:decimal(?progressPct)) AS ?goal_progress) (AVG(xsd:decimal(?avgVolatilityPct)) AS ?volatility)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:timeHorizon ?timeHorizonRaw ;
                wm:hasScenarioRebalancing ?scenarioRebalancing ;
                wm:hasInvestmentGoal ?investmentGoal .
      ?scenarioRebalancing a wm:ScenarioRebalancing .
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:progressPct ?progressPct ;
                      wm:avgVolatilityPct ?avgVolatilityPct .
    }
    GROUP BY ?investorId
  }
  BIND(STR(?timeHorizonRaw) AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  (SUM(IF(BOUND(?hasRebalancingAction), 0, 1)) AS ?missing_hasRebalancingAction)
  (SUM(IF(BOUND(?hasScenarioRebalancing), 0, 1)) AS ?missing_hasScenarioRebalancing)
  (SUM(IF(BOUND(?hasHolding), 0, 1)) AS ?missing_hasHolding)
  (SUM(IF(BOUND(?hasRiskTolerance), 0, 1)) AS ?missing_hasRiskTolerance)
  (SUM(IF(BOUND(?hasTimeHorizon), 0, 1)) AS ?missing_hasTimeHorizon)
  (SUM(IF(BOUND(?category), 0, 1)) AS ?missing_category)
  (SUM(IF(BOUND(?hasPortfolioHealth), 0, 1)) AS ?missing_hasPortfolioHealth)
  (SUM(IF(BOUND(?riskTolerance), 0, 1)) AS ?missing_riskTolerance)
  (SUM(IF(BOUND(?hasCashFlow), 0, 1)) AS ?missing_hasCashFlow)
  (SUM(IF(BOUND(?notes), 0, 1)) AS ?missing_notes)
  (SUM(IF(BOUND(?segment), 0, 1)) AS ?missing_segment)
  (SUM(IF(BOUND(?investorName), 0, 1)) AS ?missing_investorName)
  (SUM(IF(BOUND(?hasSegment), 0, 1)) AS ?missing_hasSegment)
  (SUM(IF(BOUND(?hasSectorAllocation), 0, 1)) AS ?missing_hasSectorAllocation)
  (SUM(IF(BOUND(?hasCategory), 0, 1)) AS ?missing_hasCategory)
  (SUM(IF(BOUND(?hasInvestmentGoal), 0, 1)) AS ?missing_hasInvestmentGoal)
  (SUM(IF(BOUND(?sectorFocus), 0, 1)) AS ?missing_sectorFocus)
  (SUM(IF(BOUND(?sourceTable), 0, 1)) AS ?missing_sourceTable)
  (SUM(IF(BOUND(?timeHorizon), 0, 1)) AS ?missing_timeHorizon)
  (SUM(IF(BOUND(?investmentGoal), 0, 1)) AS ?missing_investmentGoal)
  (SUM(IF(BOUND(?hasInvestmentGoalType), 0, 1)) AS ?missing_hasInvestmentGoalType)
  (SUM(IF(BOUND(?focusesOnSector), 0, 1)) AS ?missing_focusesOnSector)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:hasRebalancingAction ?hasRebalancingAction . }
  OPTIONAL { ?investor wm:hasScenarioRebalancing ?hasScenarioRebalancing . }
  OPTIONAL { ?investor wm:hasHolding ?hasHolding . }
  OPTIONAL { ?investor wm:hasRiskTolerance ?hasRiskTolerance . }
  OPTIONAL { ?investor wm:hasTimeHorizon ?hasTimeHorizon . }
  OPTIONAL { ?investor wm:category ?category . }
  OPTIONAL { ?investor wm:hasPortfolioHealth ?hasPortfolioHealth . }
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
  OPTIONAL { ?investor wm:hasCashFlow ?hasCashFlow . }
  OPTIONAL { ?investor wm:notes ?notes . }
  OPTIONAL { ?investor wm:segment ?segment . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:hasSegment ?hasSegment . }
  OPTIONAL { ?investor wm:hasSectorAllocation ?hasSectorAllocation . }
  OPTIONAL { ?investor wm:hasCategory ?hasCategory . }
  OPTIONAL { ?investor wm:hasInvestmentGoal ?hasInvestmentGoal . }
  OPTIONAL { ?investor wm:sectorFocus ?sectorFocus . }
  OPTIONAL { ?investor wm:sourceTable ?sourceTable . }
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
  OPTIONAL { ?investor wm:investmentGoal ?investmentGoal . }
  OPTIONAL { ?investor wm:hasInvestmentGoalType ?hasInvestmentGoalType . }
  OPTIONAL { ?investor wm:focusesOnSector ?focusesOnSector . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investorId) AS ?investorId)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:investmentGoal "Growth" ;
                  wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:sector "Technology" .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investorId) AS ?count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasInvestmentGoal ?investmentGoal ;
            wm:hasPortfolioHealth ?portfolioHealth ;
            wm:hasRebalancingAction ?rebalancingAction .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:shortfall ?shortfall .
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:liquidityScore ?liquidityScore .
  ?rebalancingAction a wm:RebalancingAction ;
                     wm:action ?action .
  FILTER(xsd:decimal(?shortfall) > 0)
  FILTER(xsd:decimal(?liquidityScore) < 30)
  FILTER(?action = "Sell")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasPortfolioHealth ?portfolioHealth ;
            wm:hasHolding ?portfolioHolding ;
            wm:hasCashFlow ?cashFlow .
  ?portfolioHealth wm:riskScore ?riskScore ;
                   wm:liquidityScore ?liquidityScore .
  ?portfolioHolding wm:returnsPct ?returnsPct ;
                    wm:allocationPct ?allocationPct .
  ?cashFlow wm:type ?type .
  FILTER(xsd:decimal(?riskScore) > 50)
  FILTER(xsd:decimal(?liquidityScore) < 30)
  FILTER(xsd:decimal(?returnsPct) < 0)
  FILTER(xsd:decimal(?allocationPct) > 20)
  FILTER(LCASE(STR(?type)) = "withdrawal")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon (AVG(?scenario_change) AS ?scenario_change) (AVG(?rebalancing_gap) AS ?rebalancing_gap) (AVG(?rebalancing_amount) AS ?rebalancing_amount)
WHERE {
  {
    SELECT ?investorId (COUNT(?scenario) AS ?scenario_change) (AVG(xsd:decimal(?targetAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?rebalancing_gap) (SUM(xsd:decimal(?amount)) AS ?rebalancing_amount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasScenarioRebalancing ?scenarioRebalancing ;
                wm:hasRebalancingAction ?rebalancingAction .
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
                           wm:scenario ?scenario .
      ?rebalancingAction a wm:RebalancingAction ;
                         wm:targetAllocationPct ?targetAllocationPct ;
                         wm:currentAllocationPct ?currentAllocationPct ;
                         wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasTimeHorizon ?timeHorizon .
  BIND(COALESCE(STR(?timeHorizon), "NULL") AS ?time_horizon)
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance (AVG(?goal_progress) AS ?avg_goal_progress) (AVG(?holding_gain) AS ?avg_holding_gain) (AVG(?risk_score) AS ?avg_risk_score) (AVG(?liquidity) AS ?avg_liquidity)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goal_progress)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?holding_gain)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?risk_score)
    WHERE {
      ?investor wm:hasPortfolioHealth ?health .
      ?health wm:riskScore ?riskScore .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?liquidityScore)) AS ?liquidity)
    WHERE {
      ?investor wm:hasPortfolioHealth ?health .
      ?health wm:liquidityScore ?liquidityScore .
      ?investor wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  ?investor wm:investorId ?investorId .
  ?investor wm:riskTolerance ?risk_tolerance .
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?investmentGoal a wm:InvestmentGoal ;
                  wm:belongsToInvestor ?investor ;
                  wm:investmentGoal ?goal .
  FILTER(LCASE(STR(?goal)) = "retirement planning")
  ?scenarioRebalancing a wm:ScenarioRebalancing ;
                       wm:scenarioRebalancingOfInvestor ?investor ;
                       wm:scenario ?scenario ;
                       wm:triggeredAction ?action .
  FILTER(LCASE(STR(?scenario)) = "bear market" && LCASE(STR(?action)) = "de-risking")
  ?portfolioHealth a wm:PortfolioHealth ;
                   wm:healthOfInvestor ?investor ;
                   wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?divScore) < 25)
  ?sectorAllocation a wm:SectorAllocation ;
                    wm:allocationOfInvestor ?investor ;
                    wm:sector ?sector .
  FILTER(LCASE(STR(?sector)) = "technology")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investorId) AS ?investorId)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:date ?cashFlowDate .
  FILTER (?cashFlowDate >= "2025-01-01"^^xsd:date && ?cashFlowDate <= "2025-12-31"^^xsd:date)
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:purchaseDate ?purchaseDate ;
           wm:returnsPct ?returnsPct .
  FILTER (?purchaseDate >= "2025-01-01"^^xsd:date && ?purchaseDate <= "2025-12-31"^^xsd:date)
  FILTER (xsd:decimal(?returnsPct) < 0)
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:shortfall ?shortfall .
  FILTER (xsd:decimal(?shortfall) > 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investorId) AS ?investorId)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasRebalancingAction ?action .
  ?goal a wm:InvestmentGoal ;
        wm:timeToGoalMonths ?timeToGoalMonthsRaw .
  FILTER(xsd:integer(?timeToGoalMonthsRaw) <= 12)
  ?action a wm:RebalancingAction ;
          wm:action ?actionRaw .
  FILTER(STR(?actionRaw) = "De-risking")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor_category (SUM(?holdingValue) AS ?total_holding_value) (SUM(?sectorAllocation) AS ?total_sector_allocation) (SUM(?cashFlowAmount) AS ?total_cash_flow_amount)
WHERE {
  {
    SELECT ?investorId 
           (COALESCE(SUM(xsd:decimal(?currentValue)), 0) AS ?holdingValue)
           (COALESCE(SUM(xsd:decimal(?totalInvestment)), 0) AS ?sectorAllocation)
           (COALESCE(SUM(xsd:decimal(?amount)), 0) AS ?cashFlowAmount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      OPTIONAL {
        ?holding wm:heldByInvestor ?investor .
        ?holding wm:currentValue ?currentValue .
      }
      OPTIONAL {
        ?allocation wm:allocationOfInvestor ?investor .
        ?allocation wm:totalInvestment ?totalInvestment .
      }
      OPTIONAL {
        ?cashFlow wm:cashFlowOfInvestor ?investor .
        ?cashFlow wm:amount ?amount .
      }
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:category ?investor_category_raw . }
  BIND(COALESCE(STR(?investor_category_raw), "NULL") AS ?investor_category)
}
GROUP BY ?investor_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor_category
       (AVG(xsd:decimal(?invTotalHoldingGain)) AS ?total_holding_gain)
       (AVG(xsd:decimal(?invNetCashFlow)) AS ?net_cash_flow)
       (AVG(xsd:decimal(?invAvgProgressPct)) AS ?avg_progress_pct)
       (AVG(xsd:decimal(?invAvgRiskScore)) AS ?avg_risk_score)
WHERE {
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?progressPct)) AS ?invTotalHoldingGain)
           (SUM(xsd:decimal(?amount)) AS ?invNetCashFlow)
           (AVG(xsd:decimal(?progressPct)) AS ?invAvgProgressPct)
           (AVG(xsd:decimal(?riskScore)) AS ?invAvgRiskScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL {
        ?investmentGoal a wm:InvestmentGoal ;
                        wm:belongsToInvestor ?investor ;
                        wm:progressPct ?progressPct .
      }
      OPTIONAL {
        ?cashFlow a wm:CashFlow ;
                  wm:cashFlowOfInvestor ?investor ;
                  wm:amount ?amount .
      }
      OPTIONAL {
        ?portfolioHealth a wm:PortfolioHealth ;
                         wm:healthOfInvestor ?investor ;
                         wm:riskScore ?riskScore .
      }
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL {
    ?investor wm:category ?investor_category_raw .
  }
  BIND(COALESCE(STR(?investor_category_raw), "NULL") AS ?investor_category)
}
GROUP BY ?investor_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?goalContext (SUM(?hasHoldingFlag) AS ?investorsWithHoldings) (SUM(?hasSectorAllocationFlag) AS ?investorsWithAllocations) (SUM(?hasCashFlowFlag) AS ?investorsWithCashFlow)
WHERE {
  {
    SELECT ?investorId ?riskTolerance ?goalContext
           (MAX(?hasHoldingFlag) AS ?hasHoldingFlag)
           (MAX(?hasSectorAllocationFlag) AS ?hasSectorAllocationFlag)
           (MAX(?hasCashFlowFlag) AS ?hasCashFlowFlag)
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      OPTIONAL { ?investor wm:riskTolerance ?riskToleranceRaw . }
      BIND(COALESCE(?riskToleranceRaw, "NULL") AS ?riskTolerance)
      OPTIONAL { ?investor wm:investmentGoal ?investmentGoalRaw . }
      BIND(COALESCE(?investmentGoalRaw, "NULL") AS ?goalContext)
      OPTIONAL {
        ?investor wm:hasHolding ?h .
        ?h a wm:PortfolioHolding .
        BIND(1 AS ?hasHoldingFlagInner)
      }
      OPTIONAL {
        ?investor wm:hasSectorAllocation ?sa .
        ?sa a wm:SectorAllocation .
        BIND(1 AS ?hasSectorAllocationFlagInner)
      }
      OPTIONAL {
        ?investor wm:hasCashFlow ?cf .
        ?cf a wm:CashFlow .
        BIND(1 AS ?hasCashFlowFlagInner)
      }
    }
    GROUP BY ?investorId ?riskTolerance ?goalContext
  }
}
GROUP BY ?riskTolerance ?goalContext

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(xsd:decimal(?shortfall)) AS ?avg_goal_shortfall)
       (AVG(xsd:decimal(?sectorAllocationCount)) AS ?avg_allocation_concentration)
       (AVG(xsd:decimal(?liquidityScore)) AS ?avg_health_liquidity)
       (AVG(xsd:decimal(?diversificationScore)) AS ?avg_diversification)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?shortfallRaw)) AS ?shortfall)
    WHERE {
      ?investmentGoal a wm:InvestmentGoal ;
                      wm:belongsToInvestor ?investor ;
                      wm:shortfall ?shortfallRaw .
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (COUNT(?sectorAllocation) AS ?sectorAllocationCount)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasSectorAllocation ?sectorAllocation .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?liquidityScoreRaw)) AS ?liquidityScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:liquidityScore ?liquidityScoreRaw .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?diversificationScoreRaw)) AS ?diversificationScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth a wm:PortfolioHealth ;
                       wm:diversificationScore ?diversificationScoreRaw .
    }
    GROUP BY ?investorId
  }
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskToleranceRaw .
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance)
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  ?cashFlow a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:type ?type .
  FILTER(?type = "Withdrawal")
  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:progressPct ?progressPct .
  FILTER(xsd:decimal(?progressPct) < 25)
}
GROUP BY ?investor ?investorId
HAVING (COUNT(?cashFlow) > 0 && COUNT(?goal) > 0)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance_group (AVG(?avg_cash_flow) AS ?avg_cash_flow) (AVG(?avg_scenario_change) AS ?avg_scenario_change) (AVG(?avg_allocation_concentration) AS ?avg_allocation_concentration) (AVG(?avg_sector_investment) AS ?avg_sector_investment)
WHERE {
  {
    SELECT ?investorId ?riskToleranceRaw (AVG(xsd:decimal(?amount)) AS ?avg_cash_flow)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:riskTolerance ?riskToleranceRaw .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
    }
    GROUP BY ?investorId ?riskToleranceRaw
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPct)) AS ?avg_scenario_change)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor ;
                           wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?avg_allocation_concentration) (AVG(xsd:decimal(?totalInvestment)) AS ?avg_sector_investment)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .
      ?sectorAllocation wm:allocationOfInvestor ?investor ;
                        wm:allocationPct ?allocationPct ;
                        wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?risk_tolerance_group)
}
GROUP BY ?risk_tolerance_group
